    """Return the largest prime factor of n. Assume n > 1 and is not a prime.
    """
    def is_prime(x):
        if x < 2:
            return False
        for i in range(2, int(x**0.5) + 1):
            if x % i == 0:
                return False
        return True

    # Start with the smallest prime factor
    factor = 2
    last_factor = 1

    while n > 1:
        # Find the smallest factor of n
        while n % factor != 0:
            factor += 1
        last_factor = factor

        # Divide n by its smallest factor
        while n % factor == 0:
            n //= factor

    # The last factor found is the largest prime factor
    return last_factor
